def validate_topics(track_name, topics):
    print(f"Validating {len(topics)} {track_name} topics...")
    assert len(topics) == 100, f"Expected 100 {track_name} topics, got {len(topics)}"
    seen_names = set()
    for name, subject, system, focus, ref_name, ref_url in topics:
        assert name not in seen_names, f"Duplicate topic name: {name}"
        seen_names.add(name)
        assert subject in TAXONOMY_SUBJECTS, f"Invalid subject {subject} in {name}"
        assert system in TAXONOMY_SYSTEMS, f"Invalid system {system} in {name}"
        assert len(focus) >= 30, f"Focus too short in {name}"
        assert ref_url.startswith("https://"), f"Reference URL must start with https:// in {name}"
    print(f"Validated 100 {track_name} topics successfully.")

if __name__ == "__main__":
    validate_topics("SMLE", SMLE_RAW)
    validate_topics("UHS", UHS_RAW)
    if len(HAAD_RAW) == 100:
        validate_topics("HAAD", HAAD_RAW)
        # Write output file
        out_content = f'''"""
Auto-generated topics for Mega-Batch 54 (Part B):
- 100 SMLE (Saudi Arabia) topics (1,600 -> 1,700)
- 100 UHS MBBS (Pakistan) topics (1,600 -> 1,700)
- 100 HAAD / DHA (UAE) topics (1,600 -> 1,700)
"""

SMLE_TOPICS = {repr(SMLE_RAW)}

UHS_TOPICS = {repr(UHS_RAW)}

HAAD_TOPICS = {repr(HAAD_RAW)}
'''
        with open("scripts/mega54_topics_b.py", "w", encoding="utf-8") as f:
            f.write(out_content)
        print("Wrote scripts/mega54_topics_b.py successfully.")
    else:
        print(f"Waiting for HAAD_RAW (currently {len(HAAD_RAW)} topics). Run append_haad_54.py first.")
